graphql.query:
query GetClient($id: ID!) {
  client(id: $id) {
    id
    firstName
    lastName
    email
    phone
    loyaltyPointsBalance
    customFields { key value }
  }
}

query ListClients($updatedSince: DateTime, $first: Int) {
  clients(updatedSince: $updatedSince, first: $first) {
    id
    firstName
    lastName
    email
    updatedAt
  }
}

mutation UpdateClient($input: UpdateClientInput!) {
  updateClient(input: $input) {
    id
    customFields { key value }
  }
}

query ListAppointments($locationId: ID, $status: AppointmentStatus, $since: DateTime) {
  appointments(locationId: $locationId, status: $status, since: $since) {
    id
    status
    startAt
    endAt
    client { id firstName lastName }
    staff { id displayName }
  }
}

query ListLocations {
  locations {
    id
    name
    timezone
    staff { id displayName bookable }
  }
}

query ListMemberships($clientId: ID, $status: MembershipStatus) {
  memberships(clientId: $clientId, status: $status) {
    id
    planName
    status
    renewsAt
    entitlements { service { name } remainingUses }
  }
}

mutation CreateGiftCard($input: CreateGiftCardInput!) {
  createGiftCard(input: $input) {
    id
    code
    currentBalance
    status
  }
}

mutation AdjustAccountCredit($input: CreateAccountCreditAdjustmentInput!) {
  createAccountCreditAdjustment(input: $input) {
    id
    resultingBalance
    adjustmentReason
  }
}

mutation CreateVouchers($input: VouchersCreateInput!) {
  vouchersCreate(input: $input) {
    id
    status
    expiresAt
  }
}

query GetBusiness {
  business {
    id
    name
    locations { id name address { city state } }
  }
}

query ListServiceCategories($locationId: ID!) {
  serviceCategories(locationId: $locationId) {
    id
    name
    services { id name durationMinutes priceStartingAt bookableOnline }
  }
}

query GetBookableDates($cartId: ID!, $month: String!) {
  bookableDates(cartId: $cartId, month: $month) {
    date
    hasAvailability
  }
}

query GetBookableTimes($cartId: ID!, $date: String!) {
  bookableTimes(cartId: $cartId, date: $date) {
    startAt
    staff { id displayName }
  }
}

mutation CreateCart($input: CreateCartInput!) {
  createCart(input: $input) {
    id
    status
  }
}

mutation AddCartItem($input: AddCartSelectedPurchasableItemInput!) {
  addCartSelectedPurchasableItem(input: $input) {
    id
    items { id service { name } price }
  }
}

mutation ReserveTimeslot($input: ReserveCartTimeslotInput!) {
  reserveCartTimeslot(input: $input) {
    id
    status
    reservedStartAt
  }
}

mutation AddCardPaymentMethod($input: AddCartCardPaymentMethodInput!) {
  addCartCardPaymentMethod(input: $input) {
    id
    status
  }
}

mutation CheckoutCart($input: CheckoutCartInput!) {
  checkoutCart(input: $input) {
    confirmationCode
    appointment { id startAt status }
  }
}
